import React from "react";
import Image from "../models/image";

export function capitalize(str) {
    return str.charAt(0).toUpperCase() + str.slice(1);
}

export function formatKenyaPhoneNumber(phone = "") {
    if (phone) {
        if (phone.charAt(0) == 0) {
            return phone.replace(0, '254');
        } else if (phone.substr(0, 3) === "254" && phone.length === 12) {
            return phone
        }
    }


}


const imagesTransform = (images) => {
    let transformedImages = [];

    images.map((i) => {
        transformedImages.push(
            new Image(
                i.id,
                i.image,
                i.thumbnail,
                i.title ? i.title : "",
                i.description ? i.description : "",

            )
        );
    });
    return transformedImages;
};


export { imagesTransform }